package ir.neshane.isolationprobe.recovery;

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.security.cert.*;
import java.security.spec.ECGenParameterSpec;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import javax.net.ssl.*;

/** Disposable laboratory trust only; no production identity or recovery policy. */
public final class LabRecoveryTrust {
    static final List<String> ROLES=List.of("recovery-authority","source-owner","restored-owner","recovery-executor","authority-db","source-db","restored-db","driver","client-a-old","client-a-current","client-b-old","client-b-current");
    static final class Denied extends RuntimeException { private static final long serialVersionUID=1L; Denied(String code){super(code);} }
    static void require(boolean condition,String code){if(!condition)throw new Denied(code);}
    static Map<String,String> map(String... pairs){var m=new TreeMap<String,String>();require(pairs.length%2==0,"FIELD_PAIRS");for(int i=0;i<pairs.length;i+=2)require(m.put(pairs[i],pairs[i+1])==null,"DUPLICATE_FIELD");return m;}
    static String hash(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
    static String b64(byte[] b){return Base64.getEncoder().encodeToString(b);}
    static byte[] unb64(String text){return Base64.getDecoder().decode(text);}
    static void write(OutputStream stream,Map<String,String> m)throws Exception{require(m.size()<=64,"FIELD_COUNT");var out=new DataOutputStream(stream);out.writeInt(0x44524631);out.writeInt(m.size());for(var e:new TreeMap<>(m).entrySet())for(String text:List.of(e.getKey(),e.getValue())){byte[] b=text.getBytes(StandardCharsets.UTF_8);require(b.length<=262144,"FIELD_SIZE");out.writeInt(b.length);out.write(b);}out.flush();}
    static Map<String,String> read(InputStream stream)throws Exception{var in=new DataInputStream(stream);require(in.readInt()==0x44524631,"WIRE_VERSION");int n=in.readInt();require(n>=0&&n<=64,"FIELD_COUNT");var m=new TreeMap<String,String>();String previous="";for(int i=0;i<n;i++){String[] p=new String[2];for(int j=0;j<2;j++){int size=in.readInt();require(size>=0&&size<=262144,"FIELD_SIZE");byte[] b=in.readNBytes(size);require(b.length==size,"TRUNCATED");p[j]=new String(b,StandardCharsets.UTF_8);require(Arrays.equals(b,p[j].getBytes(StandardCharsets.UTF_8)),"NON_CANONICAL_UTF8");}require(p[0].compareTo(previous)>0,"NON_CANONICAL_FIELDS");previous=p[0];m.put(p[0],p[1]);}return m;}
    static byte[] bytes(Map<String,String> m)throws Exception{var out=new ByteArrayOutputStream();write(out,m);return out.toByteArray();}
    static String packed(Map<String,String> m)throws Exception{return b64(bytes(m));}
    static Map<String,String> unpack(String text)throws Exception{return read(new ByteArrayInputStream(unb64(text)));}
    static String password(Path d)throws Exception{return Files.readString(d.resolve("store.pass")).strip();}
    static KeyStore store(Path file,Path d)throws Exception{var s=KeyStore.getInstance("PKCS12");try(var in=Files.newInputStream(file)){s.load(in,password(d).toCharArray());}return s;}
    static PrivateKey key(Path d,String file)throws Exception{return (PrivateKey)store(d.resolve(file),d).getKey("leaf",password(d).toCharArray());}
    static X509Certificate cert(Path d,String file)throws Exception{return (X509Certificate)store(d.resolve(file),d).getCertificate("leaf");}
    static SSLContext tls(Path d,boolean key)throws Exception{var tf=TrustManagerFactory.getInstance("PKIX");tf.init(store(d.resolve("trust.p12"),d));KeyManager[] managers=null;if(key){var kf=KeyManagerFactory.getInstance("SunX509");kf.init(store(d.resolve("node.p12"),d),password(d).toCharArray());managers=kf.getKeyManagers();}var c=SSLContext.getInstance("TLSv1.3");c.init(managers,tf.getTrustManagers(),new SecureRandom());return c;}
    static Map<String,String> call(Path d,String host,int port,Map<String,String> request)throws Exception{var raw=new Socket();raw.connect(new InetSocketAddress(host,port),2500);try(var socket=(SSLSocket)tls(d,true).getSocketFactory().createSocket(raw,host,port,true)){socket.setSoTimeout(60000);socket.setEnabledProtocols(new String[]{"TLSv1.3"});var p=socket.getSSLParameters();p.setEndpointIdentificationAlgorithm("HTTPS");socket.setSSLParameters(p);socket.startHandshake();require(socket.getSession().getProtocol().equals("TLSv1.3"),"TLS13_REQUIRED");write(socket.getOutputStream(),request);return read(socket.getInputStream());}}
    static String sign(Path d,Map<String,String> body)throws Exception{var s=Signature.getInstance("SHA256withECDSA");s.initSign(key(d,"signing.p12"));s.update(bytes(body));return b64(s.sign());}
    static void verify(Path d,Map<String,String> body,String signature)throws Exception{X509Certificate c;try(var in=Files.newInputStream(d.resolve("signing.cer"))){c=(X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(in);}c.checkValidity();var s=Signature.getInstance("SHA256withECDSA");s.initVerify(c.getPublicKey());s.update(bytes(body));require(s.verify(unb64(signature)),"SIGNATURE_INVALID");}
    static Map<String,String> control(Path d,Map<String,String> input)throws Exception{var m=new TreeMap<>(input);m.put("nonce",UUID.randomUUID().toString());var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(Files.readAllBytes(d.resolve("control.key")),"HmacSHA256"));m.put("mac",b64(mac.doFinal(bytes(m))));return m;}
    static void admin(Path d,Map<String,String> input,Set<String> seen)throws Exception{String sig=input.remove("mac");require(sig!=null,"ADMIN_REQUIRED");var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(Files.readAllBytes(d.resolve("control.key")),"HmacSHA256"));require(MessageDigest.isEqual(mac.doFinal(bytes(input)),unb64(sig)),"ADMIN_INVALID");require(seen.add(input.get("nonce")),"ADMIN_REPLAY");}
    @FunctionalInterface interface Handler { Map<String,String> apply(String peer,Map<String,String> request)throws Exception; }
    static void serve(Path d,String run,Handler handler)throws Exception{var server=(SSLServerSocket)tls(d,true).getServerSocketFactory().createServerSocket(8443);server.setEnabledProtocols(new String[]{"TLSv1.3"});server.setNeedClientAuth(true);for(;;){var socket=(SSLSocket)server.accept();Thread.ofVirtual().start(()->{try(socket){socket.setSoTimeout(60000);socket.startHandshake();var certificate=(X509Certificate)socket.getSession().getPeerCertificates()[0];String identity=null;for(var san:certificate.getSubjectAlternativeNames())if(san.get(0).equals(6)){require(identity==null,"AMBIGUOUS_IDENTITY");identity=(String)san.get(1);}String prefix="urn:drref:"+run+":";require(identity!=null&&identity.startsWith(prefix),"RUN_IDENTITY");var request=read(socket.getInputStream());Map<String,String> response;try{response=handler.apply(identity.substring(prefix.length()),request);}catch(Exception error){response=map("code","DENIED","reason",safe(error));}write(socket.getOutputStream(),response);}catch(Exception error){System.out.println("TLS_OR_PROTOCOL_REJECTION "+safe(error));}});}}
    static String safe(Throwable e){for(Throwable t=e;t!=null;t=t.getCause()){if(t instanceof Denied)return t.getMessage();if(t instanceof SQLException sql)return "SQLSTATE_"+sql.getSQLState();}return e.getClass().getSimpleName();}
    static void prerequisites()throws Exception{var generator=KeyPairGenerator.getInstance("EC");generator.initialize(new ECGenParameterSpec("secp256r1"));var pair=generator.generateKeyPair();var s=Signature.getInstance("SHA256withECDSA");s.initSign(pair.getPrivate());s.update(new byte[]{1,2,3});byte[] sig=s.sign();s.initVerify(pair.getPublic());s.update(new byte[]{1,2,3});require(s.verify(sig),"SIGN_POSITIVE");s.initVerify(pair.getPublic());s.update(new byte[]{3,2,1});require(!s.verify(sig),"SIGN_TAMPER");var context=SSLContext.getInstance("TLSv1.3");context.init(null,null,null);require(Arrays.asList(context.getDefaultSSLParameters().getProtocols()).contains("TLSv1.3"),"TLS13_PROVIDER");System.out.println("PASS TLSv1.3="+context.getProvider().getName()+" P256="+s.getProvider().getName()+" PKIX="+CertPathValidator.getInstance("PKIX").getProvider().getName());}
    static void tool(Path d,String... args)throws Exception{var command=new ArrayList<String>();command.add(Path.of(System.getProperty("java.home"),"bin",System.getProperty("os.name").startsWith("Windows")?"keytool.exe":"keytool").toString());command.addAll(List.of(args));var p=new ProcessBuilder(command).redirectErrorStream(true).start();String output=new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8);require(p.waitFor(60,TimeUnit.SECONDS),"KEYTOOL_TIMEOUT");if(p.exitValue()!=0)throw new Denied("KEYTOOL_FAILED:"+args[0]+":"+output.replace(password(d),"[REDACTED]").replace('\n',' '));}
    static void generate(Path d,String file,String dn,boolean ca)throws Exception{tool(d,"-genkeypair","-alias","leaf","-keyalg","EC","-groupname","secp256r1","-sigalg","SHA256withECDSA","-dname",dn,"-validity","5","-ext",ca?"BC:critical=ca:true,pathlen:0":"BC=ca:false","-ext",ca?"KU:critical=keyCertSign,cRLSign":"KU=digitalSignature","-keystore",d.resolve(file).toString(),"-storepass:file",d.resolve("store.pass").toString());}
    static void pem(Path file,String type,byte[] value)throws Exception{Files.writeString(file,"-----BEGIN "+type+"-----\n"+Base64.getMimeEncoder(64,new byte[]{10}).encodeToString(value)+"\n-----END "+type+"-----\n");}
    static void prepare(Path root,String run)throws Exception{Files.createDirectories(root);Files.writeString(root.resolve("store.pass"),b64(SecureRandom.getSeed(32)));generate(root,"root.p12","CN=DRREF Offline Root",true);tool(root,"-exportcert","-alias","leaf","-keystore",root.resolve("root.p12").toString(),"-storepass:file",root.resolve("store.pass").toString(),"-file",root.resolve("root.cer").toString());for(String role:ROLES){Path d=root.resolve(role);Files.createDirectory(d);Files.writeString(d.resolve("store.pass"),b64(SecureRandom.getSeed(32)));Files.write(d.resolve("control.key"),SecureRandom.getSeed(32));Files.copy(root.resolve("root.cer"),d.resolve("root.cer"));generate(d,"node.p12","CN="+role,false);tool(d,"-certreq","-alias","leaf","-keystore",d.resolve("node.p12").toString(),"-storepass:file",d.resolve("store.pass").toString(),"-file",d.resolve("node.csr").toString());tool(root,"-gencert","-alias","leaf","-keystore",root.resolve("root.p12").toString(),"-storepass:file",root.resolve("store.pass").toString(),"-infile",d.resolve("node.csr").toString(),"-outfile",d.resolve("node.cer").toString(),"-validity","3","-ext","BC=ca:false","-ext","KU=digitalSignature","-ext","EKU=serverAuth,clientAuth","-ext","SAN=DNS:"+role+",DNS:localhost,IP:127.0.0.1,URI:urn:drref:"+run+":"+role);tool(d,"-importcert","-noprompt","-alias","root","-file",d.resolve("root.cer").toString(),"-keystore",d.resolve("node.p12").toString(),"-storepass:file",d.resolve("store.pass").toString());tool(d,"-importcert","-noprompt","-alias","leaf","-file",d.resolve("node.cer").toString(),"-keystore",d.resolve("node.p12").toString(),"-storepass:file",d.resolve("store.pass").toString());tool(d,"-importcert","-noprompt","-alias","root","-file",d.resolve("root.cer").toString(),"-keystore",d.resolve("trust.p12").toString(),"-storepass:file",d.resolve("store.pass").toString());pem(d.resolve("pg-root.pem"),"CERTIFICATE",Files.readAllBytes(root.resolve("root.cer")));if(role.endsWith("-db")){pem(d.resolve("server.crt"),"CERTIFICATE",cert(d,"node.p12").getEncoded());pem(d.resolve("server.key"),"PRIVATE KEY",key(d,"node.p12").getEncoded());}}
        Path a=root.resolve("recovery-authority");generate(a,"signing.p12","CN=DRREF Authorization Signer",false);tool(a,"-exportcert","-alias","leaf","-keystore",a.resolve("signing.p12").toString(),"-storepass:file",a.resolve("store.pass").toString(),"-file",a.resolve("signing.cer").toString());for(String role:ROLES)if(!role.equals("recovery-authority"))Files.copy(a.resolve("signing.cer"),root.resolve(role).resolve("signing.cer"));System.out.println("Fresh private laboratory PKI prepared; no key output");}
    static Connection database(Path d,String prefix,String host,String database,String mode,String fault)throws Exception{var p=new Properties();String user=Files.readString(d.resolve(prefix+".user")).strip();p.setProperty("user",fault.equals("wrong-role")?"postgres":user);if(!fault.equals("missing"))p.setProperty("password",fault.equals("password")?"INVALID-LAB-PASSWORD":Files.readString(d.resolve(prefix+".pass")).strip());p.setProperty("sslmode",mode);p.setProperty("sslrootcert",d.resolve(fault.equals("wrong-root")?"signing.cer":"pg-root.pem").toString());p.setProperty("connectTimeout","3");p.setProperty("socketTimeout","10");return DriverManager.getConnection("jdbc:postgresql://"+host+":5432/"+database,p);}
    static void databaseGate(Path d,String cell)throws Exception{String prefix=cell.isEmpty()?"db":"db."+cell;String host=Files.readString(d.resolve("db.host")).strip(),db=Files.readString(d.resolve(prefix+".name")).strip(),ip;try(var c=database(d,prefix,host,db,"verify-full","");var s=c.createStatement();var r=s.executeQuery("SELECT ssl,version,current_setting('fsync'),current_setting('synchronous_commit'),current_setting('full_page_writes'),(SELECT rolsuper OR rolbypassrls OR rolcreatedb OR rolcreaterole FROM pg_roles WHERE rolname=current_user),host(inet_server_addr()) FROM pg_stat_ssl WHERE pid=pg_backend_pid()")){require(r.next()&&r.getBoolean(1)&&r.getString(2).equals("TLSv1.3")&&r.getString(3).equals("on")&&r.getString(4).equals("on")&&r.getString(5).equals("on")&&!r.getBoolean(6),"DATABASE_TLS_DURABILITY_ROLE_GATE");ip=r.getString(7);}
        for(String fault:List.of("plaintext","password","missing","cross-database","wrong-role","wrong-hostname","wrong-root")){boolean denied=false;String state="";String target=fault.equals("cross-database")?(db.equals("dr_a")?"dr_b":"dr_a"):db;try(var c=database(d,prefix,fault.equals("wrong-hostname")?ip:host,target,fault.equals("plaintext")?"disable":"verify-full",fault)){require(c.isClosed(),"UNAUTHORIZED_DATABASE_CONNECTION");}catch(SQLException error){denied=true;state=error.getSQLState();}boolean expected=switch(fault){case "password"->"28P01".equals(state);case "missing"->"08004".equals(state)||"28P01".equals(state);case "wrong-hostname","wrong-root"->"08006".equals(state);default->"28000".equals(state)||"42501".equals(state);};require(denied&&expected,"DATABASE_NEGATIVE_GATE:"+fault+":"+state);System.out.println("PASS "+fault+" SQLSTATE="+state);}
        try(var c=database(d,prefix,host,db,"verify-full","");var s=c.createStatement()){boolean denied=false;try{s.execute("SET ROLE postgres");}catch(SQLException e){denied="42501".equals(e.getSQLState());}require(denied,"PRIVILEGE_ESCALATION_GATE");}
        if(!cell.isEmpty())try(var c=database(d,"runtime."+cell,host,db,"verify-full","");var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM lab_data.markers")){require(r.next()&&r.getLong(1)==0,"QUARANTINE_RUNTIME_EXPOSURE");System.out.println("PASS runtime role TLS/SCRAM and zero quarantine rows");}
        System.out.println("PASS PostgreSQL verify-full TLSv1.3 SCRAM durability and nonprivileged role gate "+db);}
    static void staleCredential(Path d)throws Exception{try(var source=database(d,"db.a","source-db","dr_a","verify-full","");var s=source.createStatement();var r=s.executeQuery("SELECT 1")){require(r.next(),"OLD_SOURCE_CREDENTIAL_POSITIVE");}boolean denied=false;try(var target=database(d,"db.a","restored-db","dr_a","verify-full","")){require(target.isClosed(),"OLD_CREDENTIAL_RESTORED");}catch(SQLException error){denied="28P01".equals(error.getSQLState());}require(denied,"OLD_SOURCE_CREDENTIAL_ACCEPTED_BY_RESTORED_TARGET");System.out.println("PASS old source credential rejected by restored target SQLSTATE=28P01");}
    public static void main(String[] args)throws Exception{switch(args[0]){case "--prerequisites":prerequisites();break;case "--prepare":prepare(Path.of(args[1]),args[2]);break;case "--database-gate":databaseGate(Path.of(args[1]),args.length>2?args[2]:"");break;case "--stale-database-credential":staleCredential(Path.of(args[1]));break;default:throw new Denied("MODE");}}
    private LabRecoveryTrust(){ }
}
